// Generated by `npm run toolkits:sync` in the CMS repository (toolkits/client). Do not edit here.
// Public URLs: the API already delivers them in the project's format (meta.url,
// menus, terms, sitemap). These helpers exist for what a site must build itself:
// route patterns, listing pages, locale detection and free internal links.
// They mirror cms/server/src/content/urls.ts.

import type { Entry, LocaleFormat, LocaleUrlMode, Schema } from "./types";

const MODES: readonly LocaleUrlMode[] = ["prefix", "prefix-all", "domain", "none"];

/** The project's locale URL format from its schema; `fallback` (an env var, say) is used only when the server does not deliver it. */
export function localeFormat(schema: Pick<Schema, "locales" | "defaultLocale" | "localeUrls" | "localeDomains">, fallback?: { mode?: string; domains?: Record<string, string> }): LocaleFormat {
  const raw = schema.localeUrls ?? fallback?.mode ?? "prefix";
  const mode = (MODES as readonly string[]).includes(raw) ? (raw as LocaleUrlMode) : "prefix";
  return { locales: schema.locales, defaultLocale: schema.defaultLocale, mode, domains: schema.localeDomains ?? fallback?.domains ?? {} };
}

/** Puts a locale-free path where the format says; `placed` means the path already carries its locale. */
function place(path: string, locale: string, format: LocaleFormat, placed: boolean) {
  const base = format.mode === "domain" ? format.domains[locale] : undefined;
  if (base) return `${base}${path === "/" ? "" : path}`;
  if (placed || format.mode === "none" || ((format.mode === "prefix" || format.mode === "domain") && locale === format.defaultLocale)) return path;
  return `/${locale}${path === "/" ? "" : path}`;
}

/** Fills "/blog/{slug}" and places the locale. `{locale}` inside the pattern is never prefixed again. */
export function fillPattern(pattern: string, values: { slug: string; id?: string; locale: string }, format: LocaleFormat) {
  const path = pattern.replace(/\{(\w+)\}/g, (_, key: string) => (key === "slug" ? values.slug : key === "locale" ? values.locale : key === "id" ? (values.id ?? values.slug) : ""));
  return place(path, values.locale, format, pattern.includes("{locale}"));
}

/** The locale-free path a collection lists at: "/blog/{slug}" lists at "/blog". */
export const listingPath = (urlPattern: string | null | undefined) => urlPattern?.replace(/\/?\{[^}]+\}.*$/, "") || "/";

/** "/blog/{slug}" lists at "/blog"; in another locale wherever the format puts it ("/en/blog"). */
export function listingUrl(urlPattern: string | null | undefined, locale: string, format: LocaleFormat) {
  return place(listingPath(urlPattern), locale, format, !!urlPattern?.includes("{locale}"));
}

/** A free internal path ("/contato") in a locale; external links stay as they are. */
export function localizePath(path: string, locale: string, format: LocaleFormat) {
  if (!path.startsWith("/") || path.startsWith("//")) return path;
  return place(path, locale, format, path === `/${locale}` || path.startsWith(`/${locale}/`));
}

/** The path part of a public URL (domain URLs lose their origin); "/" for the root. */
export const pathOf = (urlOrEntry: string | Pick<Entry, "meta"> | null | undefined) => {
  const url = typeof urlOrEntry === "string" ? urlOrEntry : urlOrEntry?.meta.url;
  if (!url) return null;
  return url.replace(/^https?:\/\/[^/]+/, "").replace(/\/+$/, "") || "/";
};

/**
 * The locale a request path (and host, for the `domain` mode) belongs to, with the
 * locale-free rest of the path. Unknown prefixes fall to the default locale.
 */
export function localeOfPath(pathname: string, format: LocaleFormat, host?: string): { locale: string; path: string } {
  const clean = pathname.replace(/\/+$/, "") || "/";
  if (format.mode === "domain" && host) {
    const hit = Object.entries(format.domains).find(([, base]) => base.replace(/^https?:\/\//, "").replace(/\/.*$/, "") === host.replace(/:\d+$/, ""));
    if (hit) return { locale: hit[0], path: clean };
  }
  if (format.mode !== "none") {
    const first = clean.slice(1).split("/")[0] as string;
    if (format.locales.includes(first)) return { locale: first, path: clean.slice(first.length + 1) || "/" };
  }
  return { locale: format.defaultLocale, path: clean };
}

/**
 * The route pattern of a type in one locale, in the `[param]` notation most routers
 * share: "/blog/{slug}" in "en" under the prefix format is "/en/blog/[slug]".
 */
export function routePattern(urlPattern: string, locale: string, format: LocaleFormat) {
  const url = fillPattern(urlPattern, { slug: "{slug}", id: "{id}", locale }, format).replace(/^https?:\/\/[^/]+/, "");
  return (url.replace(/\{(\w+)\}/g, "[$1]") || "/").replace(/\/+$/, "") || "/";
}
